 Check(TryRegisterProcessingRecovered(owner,identity,state,address,admission,publication,proof),"exact saved pair and native proof registers unattended binding");var retained=bindings.GetValue(state,_=>new Dictionary<string,BindingFixture>())["job"];Check(retained.Player==null&&retained.IsProcessingCurrent()&&!retained.IsCurrent(),"null player processing grants no live effect authority");Check(TryRegisterProcessingRecovered(owner,identity,state,address,admission,publication,proof)&&ReferenceEquals(retained,bindings.GetValue(state,_=>null)["job"]),"retry preserves original binding");
